&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_学んだ教訓&quot;&gt;学んだ教訓&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam ArrowColor #444444

rectangle &quot;**ローカルインストール**
 ホーム内&quot; as install #LightGreen {
    card &quot;sudoを使わずに
 CSS/configを変更する&quot; as i1
    card &quot;opencode+LLM できます
 すべてを変更&quot; as i2
    card &quot;ロールバック =
 タイムスタンプ付きバックアップを復元する&quot; as i3
}

rectangle &quot;**CSS カスタマイズ**\nズーム vs フォントサイズ&quot; as css #LightYellow {
    card &quot;ズーム &amp;gt; フォントサイズ
 コンポーネントリスト&quot; as c1
    card &quot;Layout JS オーバーライド
 height/line-height&quot; as c2
    card &quot;拡張機能 Custom CSS
 有効化が必要
 手動 (Ctrl+Shift+P)&quot; as c3
}

rectangle &quot;**自動化**
アップデートスクリプト&quot; as auto #LightCoral {
    card &quot;再パッチ CSS
各アップデート後&quot; as a1
    card &quot;チェックサムを削除
 product.json&quot; as a2
    card &quot;タイムスタンプ付きバックアップ
置換前に&quot; as a3
}

install -right-&amp;gt; css : ensuite
css -right-&amp;gt; auto : enfin

note top of install
  Contrôle total sans élévation
  de privilèges
end note

note top of auto
  Sans script, chaque MAJ
  efface les patches CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ホームへのインストールはすべてを解放する&quot;&gt;ホームへのインストールはすべてを解放する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ローカルインストールの`~/apps`VS Code を完全に制御します :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;なし`sudo`CSSまたは設定を変更するために&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;opencode+LLMエージェントは、IDEの設定ファイルとアセットに書き込むことができます&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;簡単なロールバック : タイムスタンプ付きバックアップを復元&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zoom_font_size_リストコンポーネントのために&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; リストコンポーネントのために&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code は JavaScript を使って行の高さを制御します。変更`font-size`レイアウトエンジンが割り当てた高さに変更を加えることができないと、テキストがはみ出します。 プロパティ`zoom`親コンテナ上で全てを比例的に拡大し、この問題を回避します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_カスタム_css_拡張機能は明示的なアクティベーションを必要とします&quot;&gt;カスタム CSS 拡張機能は明示的なアクティベーションを必要とします。&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;これは「set and forget」な設定ではありません。カスタム CSS ファイルの各変更については、コマンドパレットから「Enable Custom CSS and JS」を再実行する必要があります (&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_アップデートスクリプトは必須です&quot;&gt;アップデートスクリプトは必須です&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;スクリプトがない場合、VS Codeの更新ごとにワークベンチのCSSパッチが削除されます。スクリプト`vscode-update.sh`ダウンロード、置換、再パッチ、およびチェックサムのクリーニングを自動化する。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_クイックリファレンス&quot;&gt;クイックリファレンス&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;VS Code のダウンロード： &lt;a href=&quot;https://code.visualstudio.com/Download&quot; class=&quot;bare&quot;&gt;https://code.visualstudio.com/Download&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�拡張機能 カスタム CSS と JS ローダー :`be5invis.vscode-custom-css`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;問題：VS Code がエクスプローラーのフォント用のネイティブ設定を要求していますhttps://github.com/microsoft/vscode/issues/149[github.com/microsoft/vscode#149]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

