&lt;li&gt;&lt;a href=&quot;#_オプション_2_外部画像&quot;&gt;オプション 2 : 外部画像&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_オプション3_カスタムcssロール&quot;&gt;オプション3 : カスタムCSSロール&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_オプション4_htmlインジェクション_採用された解決策&quot;&gt;オプション4 : HTMLインジェクション (採用された解決策)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_解決策_htmlインジェクション&quot;&gt;解決策 : HTMLインジェクション &lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_動作原理&quot;&gt;動作原理&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_実装&quot;&gt;実装&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_cssプロパティの説明&quot;&gt;CSSプロパティの説明&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_完全な例&quot;&gt;完全な例&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_最適化とベストプラクティス&quot;&gt;最適化とベストプラクティス&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_明るい色を管理する&quot;&gt;明るい色を管理する&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_正方形のサイズを調整する&quot;&gt;正方形のサイズを調整する&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_バリエーションを作成する&quot;&gt;バリエーションを作成する&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_色付きの円&quot;&gt;色付きの円&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_色付きの枠線がある正方形&quot;&gt;色付きの枠線がある正方形&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ソリューションアーキテクチャ&quot;&gt;ソリューションアーキテクチャ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_利点と制限&quot;&gt;利点と制限&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_利点&quot;&gt;利点&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_制限&quot;&gt;制限&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_アクセシビリティの向上&quot;&gt;アクセシビリティの向上&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_具体例テーマのドキュメンテーション&quot;&gt;具体例：テーマのドキュメンテーション&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_リソース&quot;&gt;リソース&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_導入&quot;&gt;導入&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;技術ドキュメントを作成する際、特にスタイルガイドやユーザーインターフェース仕様では、カラーパレットを表示することがよくあります。AsciiDoc はドキュメント作成に非常に強力ですが、カラーサンプルを表示するためのネイティブな構文は提供されていません。この記事ではこの問題を検討し、HTML インジェクションに基づくエレガントな解決策を提案します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_問題&quot;&gt;問題&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用コンテキスト&quot;&gt;使用コンテキスト&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ウェブアプリケーションテーマのCSS変数をドキュメントしていると想像してください。次のものが必要です：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;16進数のカラーコードをリスト&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;各色の視覚的なプレビューを表示&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ソースドキュメントの可読性を維持する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;静的サイトジェネレーター（JBakeなど）との互換性を確保する&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;技術ライター&quot; as writer
actor &quot;読者&quot; as reader

rectangle &quot;AsciiDoc ドキュメンテーション&quot; {
  usecase &quot;カラーパレットをドキュメントする&quot; as UC1
  usecase &quot;16進数コードを表示&quot; as UC2
  usecase &quot;色を表示&quot; as UC3
  usecase &quot;静的サイトを生成&quot; as UC4
  usecase &quot;ドキュメントを参照&quot; as UC5
}

writer --&amp;gt; UC1
UC1 ..&amp;gt; UC2 : include
UC1 ..&amp;gt; UC3 : include
UC1 --&amp;gt; UC4
UC4 --&amp;gt; UC5
UC5 &amp;lt;-- reader
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_考えられるアプローチ&quot;&gt;考えられるアプローチ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;いくつかの解決策を検討することができます。AsciiDocドキュメントで色を表示するために：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;可能な解決策&quot; {
  component &quot;Unicode文字&quot; as unicode
  component &quot;外部の画像&quot; as images
  component &quot;カスタムCSSロール&quot; as css
  component &quot;HTMLインジェクション&quot; as html
}

package &quot;評価基準&quot; {
  component &quot;シンプルさ&quot; as simple
  component &quot;�携帯性&quot; as portable
  component &quot;パーソナライズ&quot; as custom
  component &quot;メンテナンス&quot; as maintain
}

unicode -down-&amp;gt; simple : ✓
unicode -down-&amp;gt; portable : ✓
unicode -down-&amp;gt; custom : ✗

images -down-&amp;gt; simple : ✗
images -down-&amp;gt; portable : ✗
images -down-&amp;gt; custom : ✓

css -down-&amp;gt; simple : ~
css -down-&amp;gt; portable : ✗
css -down-&amp;gt; custom : ✓

html -down-&amp;gt; simple : ✓
html -down-&amp;gt; portable : ✓
html -down-&amp;gt; custom : ✓✓
html -down-&amp;gt; maintain : ✓

note right of html
  Solution recommandée
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_オプション_1_unicode文字&quot;&gt;オプション 1 : Unicode文字&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Unicode文字を使用して`&amp;#9632;`(■) 簡単だが限定的である :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* ■ --accent-color: #7952b3 (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;制限&lt;/strong&gt; : 色の制御はありません、システムフォントに依存します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_オプション_2_外部画像&quot;&gt;オプション 2 : 外部画像&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;各色ごとに PNG または SVG の画像を作成する：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* image:colors/violet.svg[width=16] --accent-color: #7952b3&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;制限&lt;/strong&gt; :重いメンテナンス、ファイルの増殖、自動同期なし。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_オプション3_カスタムcssロール&quot;&gt;オプション3 : カスタムCSSロール&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CSSクラスを定義し、AsciiDocのロールを使用して適用する：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* [.color-violet]##■## --accent-color: #7952b3&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;制限&lt;/strong&gt; : 外部スタイルシートが必要、すべての可能な色の事前定義が必要&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_オプション4_htmlインジェクション_採用された解決策&quot;&gt;オプション4 : HTMLインジェクション (採用された解決策)&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;マクロを使用する``HTMLをインラインスタイルで注入するために :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;
background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;]
--accent-color: #7952b3 (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_解決策_htmlインジェクション&quot;&gt;解決策 : HTMLインジェクション &lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_動作原理&quot;&gt;動作原理&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;マクロ``AsciiDoc では、AsciiDoc プロセッサーによって解釈されない生のコンテンツを挿入できます。これにより、インライン CSS スタイルを持つ HTML を直接挿入できます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
participant &quot;ドキュメント\nAsciiDoc&quot; as doc
participant &quot;プロセッサー
AsciiDoc&quot; as processor
participant &quot;パス:[] マクロ&quot; as pass
participant &quot;HTML
最終&quot; as html

doc -&amp;gt; processor : Analyse document
processor -&amp;gt; pass : Détecte pass:[]
pass -&amp;gt; processor : Retourne HTML brut
processor -&amp;gt; html : Insère sans transformation
html -&amp;gt; html : Navigateur applique styles
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_実装&quot;&gt;実装&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ここに注入するHTML構造は：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;span style=&quot;display:inline-block;
             width:1em;
             height:1em;
             background:#7952b3;
             vertical-align:middle;
             margin-right:0.5em&quot;&amp;gt;
&amp;lt;/span&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_cssプロパティの説明&quot;&gt;CSSプロパティの説明&lt;/h4&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 75%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;所有&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;機能&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;display:inline-block&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;インラインフローに留まりながら width/height を設定できるようにする&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;width:1em; height:1em&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;フォントサイズに対する正方形のサイズ (レスポンシブ)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;background:#7952b3&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;表示する色（ニーズに応じて変数）&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;vertical-align:middle&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;正方形を隣接するテキストに合わせて揃える&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;margin-right:0.5em&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;正方形とテキストの間隔&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_完全な例&quot;&gt;完全な例&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;テーマパレットの文書化例を以下に示します：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;== Thème Clair

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#f8f9fa` (blanc cassé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#7952b3` (violet Bootstrap)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#61428f;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-hover: `#61428f` (violet plus foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --card-bg: `#ffffff` (blanc)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次のレンダリングを生成する：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ライトテーマ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --bg-primary:`#f8f9fa`(オフホワイト)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --text-primary:`#212529`(非常に暗い黒)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --accent-color:`#7952b3`(バイオレット Bootstrap)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#61428f;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --accent-hover:`#61428f`(より暗い紫)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --card-bg:`#ffffff`(白)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_最適化とベストプラクティス&quot;&gt;最適化とベストプラクティス&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_明るい色を管理する&quot;&gt;明るい色を管理する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;非常に薄い色（白、非常に薄いグレー）の場合は、白い背景でも見えるように枠線を追加してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;
background:#ffffff;border:1px solid #ccc;
vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;�灰色の境界線`border:1px solid #ccc`) は白い背景上の白い正方形を区切ることができます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_正方形のサイズを調整する&quot;&gt;正方形のサイズを調整する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;必要に応じて正方形のサイズを調整できます：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1.5em;height:1.5em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Grand carré
* pass:[&amp;lt;span style=&quot;display:inline-block;width:0.8em;height:0.8em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Petit carré&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;単位の使用`em`フォントサイズに合わせて正方形が適応することを保証します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_バリエーションを作成する&quot;&gt;バリエーションを作成する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;特定のニーズに対して、さまざまな形を作ることができます：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_色付きの円&quot;&gt;色付きの円&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;border-radius:50%;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Cercle violet&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_色付きの枠線がある正方形&quot;&gt;色付きの枠線がある正方形&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:3px solid #7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Bordure violette&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ソリューションアーキテクチャ&quot;&gt;ソリューションアーキテクチャ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
package &quot;ドキュメントワークフロー&quot; {
  [Document AsciiDoc\navec pass macro] as asciidoc
  [Processeur JBake] as jbake
  [Site HTML statique] as html
  [Navigateur Web] as browser
}

asciidoc --&amp;gt; jbake : 1. Compilation
jbake --&amp;gt; html : 2. Génération
html --&amp;gt; browser : 3. Affichage
browser --&amp;gt; browser : 4. Rendu CSS

note right of asciidoc
  Contient les balises
  pass:[] avec HTML inline
end note

note right of jbake
  Préserve le HTML
  dans pass:[]
end note

note right of browser
  Applique les styles
  inline CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_利点と制限&quot;&gt;利点と制限&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_利点&quot;&gt;利点&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;自律性 : 外部ファイルへの依存はありません&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�✓ &lt;strong&gt;ポータビリティ&lt;/strong&gt; : すべての AsciiDoc プロセッサーで動作します&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�✓ &lt;strong&gt;同期化&lt;/strong&gt; : カラーコードはHTMLに直接記述されています&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�✓ &lt;strong&gt;柔軟性&lt;/strong&gt; : スタイルの完全なカスタマイズ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;メンテナンス&lt;/strong&gt; : 16進コードの簡単な変更&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;JBake 互換性&lt;/strong&gt; : 静的サイトジェネレーターと完全に互換性があります&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_制限&quot;&gt;制限&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;冗長&lt;/strong&gt; : HTMLコードの繰り返しは、AsciiDocソース内&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;ソースの可読性&lt;/strong&gt; : ソースドキュメントはそれほどきれいではない&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;アクセシビリティ&lt;/strong&gt; : ネイティブな代替テキストはありません（手動で追加する必要があります）&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_アクセシビリティの向上&quot;&gt;アクセシビリティの向上&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;スクリーンリーダーが読めるように四角をアクセシブルにする：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span role=&quot;img&quot; aria-label=&quot;Couleur violet Bootstrap&quot;
style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;
vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;]
--accent-color: `#7952b3` (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;属性`role=&quot;img&quot;` et `aria-label`補助技術が視覚コンテンツを理解し、説明できるようにします。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_具体例テーマのドキュメンテーション&quot;&gt;具体例：テーマのドキュメンテーション&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;複数のテーマを文書化した完全な例 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Guide des couleurs de l&#39;application

== Thème Clair (`:root`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#f8f9fa` (blanc cassé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#7952b3` (violet Bootstrap)

== Thème Sombre (`[data-bs-theme=&quot;dark&quot;]`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #999;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#ffffff` (blanc)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#0d6efd;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#0d6efd` (bleu Bootstrap)

== Thème Contraste Élevé (`[data-bs-theme=&quot;high-contrast&quot;]`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#000000;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#000000` (noir)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #000;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#ffffff` (blanc)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#00ff00;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#00ff00` (vert vif)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;マクロを介したHTMLインジェクション``AsciiDocは、技術文書で色見本を表示するためのエレガントで実用的なソリューションを提供します。やや冗長ではあるが、このアプローチは最大限の移植性と簡素化されたメンテナンスを保証します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この技術は外部の設定や追加のスタイルシートを必要とせず、JBakeおよびすべての標準的なAsciiDocプロセッサとすぐに動作します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;最初の色付きの正方形を作成したら、HTMLコードをコピー＆ペーストし、16進数コードを変更するだけで、すぐに完全なパレットを作成できます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この技術は、カスタマイズされたビジュアルレンダリングを必要とする他のユースケースにも拡張できます：アイコン、バッジ、シンプルなグラフ、またはスタイルを正確に制御する必要のあるすべてのビジュアル要素。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_リソース&quot;&gt;リソース&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.asciidoctor.org/asciidoc/latest/pass/pass-macro/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;AsciiDoc ドキュメント : pass macro&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://jbake.org/docs/2.6.7/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;JBakeドキュメンテーション&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://developer.mozilla.org/fr/docs/Web/CSS/color_value&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;MDN : CSSのカラー値&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;掲載された記事 2025-11-01&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_はじめに&quot;&gt;はじめに&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ユースケース図_use_case&quot;&gt;ユースケース図 (Use Case)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_国際化のアーキテクチャ&quot;&gt;国際化のアーキテクチャ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_構造図ファイル構成&quot;&gt;構造図（ファイル構成）&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_なぜこのアプローチ&quot;&gt;なぜこのアプローチ？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_コンポーネント図&quot;&gt;コンポーネント図&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_thymeleafを使用したテンプレートの国際化&quot;&gt;Thymeleafを使用したテンプレートの国際化&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_メッセージファイルの構造&quot;&gt;メッセージファイルの構造&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_メッセージファイルの内容&quot;&gt;メッセージファイルの内容&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_テンプレートでの使用&quot;&gt;テンプレートでの使用&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_シーケンス図_i18nの解決&quot;&gt;シーケンス図 - i18nの解決&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jbakeにおけるロケールの設定&quot;&gt;JBakeにおけるロケールの設定&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_記事の国際化フォルダーごとの整理&quot;&gt;記事の国際化：フォルダーごとの整理&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_フローチャート_flow_生成&quot;&gt;フローチャート (Flow) - 生成&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_フォルダ構造&quot;&gt;フォルダ構造&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_このアプローチの利点&quot;&gt;このアプローチの利点&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_記事のメタデータ&quot;&gt;記事のメタデータ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_urlの設定&quot;&gt;URLの設定&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_多言語表示用テンプレート&quot;&gt;多言語表示用テンプレート&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_言語セレクタ付き記事テンプレート&quot;&gt;言語セレクタ付き記事テンプレート&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_言語でフィルタリングされたインデックス&quot;&gt;言語でフィルタリングされたインデックス&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_言語間ナビゲーション&quot;&gt;言語間ナビゲーション&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_グローバル言語セレクター&quot;&gt;グローバル言語セレクター&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_フローチャート_ユーザーによる読み取り&quot;&gt;フローチャート - ユーザーによる読み取り&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_セレクター用のcssスタイル&quot;&gt;セレクター用のCSSスタイル&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_言語別_rss_フィード&quot;&gt;言語別 RSS フィード&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_良いプラクティスとコツ&quot;&gt;良いプラクティスとコツ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_記事識別子の一貫性&quot;&gt;記事識別子の一貫性&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_一貫性のある日付&quot;&gt;2. 一貫性のある日付&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_多言語タグ&quot;&gt;3. 多言語タグ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_未翻訳記事の管理&quot;&gt;4. 未翻訳記事の管理&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_多言語サイトマップ&quot;&gt;5. 多言語サイトマップ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_配置図&quot;&gt;配置図&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_はじめに&quot;&gt;はじめに&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;静的サイトの国際化（i18n）は一見複雑に見えるかもしれませんが、JBakeとThymeleafを組み合わせることで、多言語サイトを作成するための洗練されたソリューションが提供されます。この記事では、私のブログでi18nをどのように実装したかを紹介し、テンプレートと複数言語での記事管理の両方をカバーします。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ユースケース図_use_case&quot;&gt;ユースケース図 (Use Case)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;著者&quot; as author
actor &quot;リーダー FR&quot; as reader_fr
actor &quot;リーダー EN&quot; as reader_en

rectangle &quot;JBake多言語サイト&quot; {
  usecase &quot;FR記事を書く&quot; as UC1
  usecase &quot;記事をENで書く&quot; as UC2
  usecase &quot;i18nメッセージを設定する&quot; as UC3
  usecase &quot;サイト生成&quot; as UC4
  usecase &quot;FR記事を読む&quot; as UC5
  usecase &quot;記事を読む EN&quot; as UC6
  usecase &quot;言語を変更&quot; as UC7
  usecase &quot;利用可能な翻訳を見る&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_国際化のアーキテクチャ&quot;&gt;国際化のアーキテクチャ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちのアプローチは2つの柱に基づいています：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;テンプレートのi18n&lt;/strong&gt;: インターフェース要素用のThymeleafメッセージファイルの使用&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;コンテンツの i18n&lt;/strong&gt;言語ごとに記事を整理するための専用フォルダ構造&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_構造図ファイル構成&quot;&gt;構造図（ファイル構成）&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_なぜこのアプローチ&quot;&gt;なぜこのアプローチ？&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この分離により、以下のことが可能になります :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;言語に関わらず、インターフェースの一貫性を維持する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;コンテンツと記事の翻訳を独立して管理する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;新しい言語の追加を大規模なリファクタリングなしで容易にする&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;特定の言語でのみ利用可能な記事を許可する&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_コンポーネント図&quot;&gt;コンポーネント図&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;出典&quot; {
  folder &quot;content/blog/2025/&quot; {
    folder &quot;fr/&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;en/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;テンプレート/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;メッセージ/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake エンジン&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;生成されたサイト&quot; {
  folder &quot;fr/&quot; {
    folder &quot;ブログ/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;en/&quot; {
    folder &quot;ブログ/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_thymeleafを使用したテンプレートの国際化&quot;&gt;Thymeleafを使用したテンプレートの国際化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_メッセージファイルの構造&quot;&gt;メッセージファイルの構造&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;最初の手順は、サポートされている各言語用のプロパティファイルを作成することです：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_メッセージファイルの内容&quot;&gt;メッセージファイルの内容&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ファイルの例です`messages_fr.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;そしてその英語訳`messages_en.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_テンプレートでの使用&quot;&gt;テンプレートでの使用&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Thymeleafのテンプレートでは、構文を使ってください`#{}`メッセージにアクセスする:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_シーケンス図_i18nの解決&quot;&gt;シーケンス図 - i18nの解決&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc
パーサー&quot; as parser
participant &quot;Thymeleaf\nエンジン&quot; as thymeleaf
participant &quot;I18n
リゾルバー&quot; as i18n
database &quot;messages_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;ホーム&quot;
i18n --&amp;gt; thymeleaf: &quot;ホーム&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;家&quot;
i18n --&amp;gt; thymeleaf: &quot;家&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jbakeにおけるロケールの設定&quot;&gt;JBakeにおけるロケールの設定&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;あなたのファイルで`jbake.properties`, デフォルトロケールを設定してください :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_記事の国際化フォルダーごとの整理&quot;&gt;記事の国際化：フォルダーごとの整理&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_フローチャート_flow_生成&quot;&gt;フローチャート (Flow) - 生成&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;各AsciiDocファイルごとに&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;各テンプレートに対して&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;コンテンツフィルタリング&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_フォルダ構造&quot;&gt;フォルダ構造&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ファイル名にサフィックスを使用する代わりに、フォルダによる整理を選択しました：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_このアプローチの利点&quot;&gt;このアプローチの利点&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この構造にはいくつかの利点があります：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;明確な分離&lt;/strong&gt;各言語には独自のスペースがあります&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;�柔軟な命名&lt;/strong&gt;: ファイルは言語によって異なる名前になる可能性があります&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;スケーラビリティ&lt;/strong&gt;新しい言語を追加するのが簡単&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;自然な組織&lt;/strong&gt;: JBakeの時間的論理に従う&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_記事のメタデータ&quot;&gt;記事のメタデータ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;各記事は翻訳間のリンクを可能にするためにメタデータを含まなければなりません。以下に例を示します：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;フランス語版&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;英語版&lt;/strong&gt;(&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;属性`:jbake-article-id:`は重要です：それは、同じ記事のさまざまな訳を結びつけることを可能にします。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_urlの設定&quot;&gt;URLの設定&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;中に`jbake.properties`, URLパターンを言語を含むように設定してください :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;これにより、次のような URL が生成されます：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_多言語表示用テンプレート&quot;&gt;多言語表示用テンプレート&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_言語セレクタ付き記事テンプレート&quot;&gt;言語セレクタ付き記事テンプレート&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;テンプレートを作成してください`post.html`利用可能な翻訳を表示します :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_言語でフィルタリングされたインデックス&quot;&gt;言語でフィルタリングされたインデックス&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;各言語向けのインデックステンプレートを作成してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(フランス語インデックス) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(英語インデックス) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_言語間ナビゲーション&quot;&gt;言語間ナビゲーション&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_グローバル言語セレクター&quot;&gt;グローバル言語セレクター&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_フローチャート_ユーザーによる読み取り&quot;&gt;フローチャート - ユーザーによる読み取り&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;メインテンプレートに言語セレクターを追加してください:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_セレクター用のcssスタイル&quot;&gt;セレクター用のCSSスタイル&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_言語別_rss_フィード&quot;&gt;言語別 RSS フィード&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;言語別にRSSフィードを分けるには、個別のテンプレートを作成してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(フランス語のフラックス) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_良いプラクティスとコツ&quot;&gt;良いプラクティスとコツ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_記事識別子の一貫性&quot;&gt;記事識別子の一貫性&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;必ず…してください`:jbake-article-id:`すべての同じ記事の翻訳に対して同じです。一貫したフォーマットを使用してください :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;普遍性のために英語の識別子を使用してください&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;単語を区切るためにハイフンを使用してください&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;特殊文字を避けてください&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_一貫性のある日付&quot;&gt;2. 一貫性のある日付&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;記事のすべての翻訳は、同じ公開日である必要があります (&lt;code&gt;:jbake-date:&lt;/code&gt;). これは並び替えと時系列表示を容易にします。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_多言語タグ&quot;&gt;3. 多言語タグ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;タグについては、2つのオプションがあります。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;オプション1 : 英語の普遍的なタグ&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;オプション2: マッピングを使ってタグを翻訳&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_未翻訳記事の管理&quot;&gt;4. 未翻訳記事の管理&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;すべての記事を訳す必要はありません。ある記事が一方の言語だけに存在する場合、他方の言語のリストには表示されません。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_多言語サイトマップ&quot;&gt;5. 多言語サイトマップ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;すべての言語を含むサイトマップを生成してください :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBakeとThymeleafを使用したサイトの国際化は、堅牢で保守しやすいアプローチです。テンプレート（メッセージファイルを通じて）とコンテンツ（フォルダ構成を通じて）の国際化を分離することで、柔軟で容易に拡張できるシステムを得ることができます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;覚えておくべき重要なポイント :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Thymeleafメッセージファイル&lt;/strong&gt;ユーザーインターフェイスのために&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;フォルダ別の整理&lt;/strong&gt;(年/言語) の記事&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;記事ID&lt;/strong&gt;翻訳をリンクするために&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;�専用テンプレート&lt;/strong&gt;各言語に対して&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;明示的なURL&lt;/strong&gt;言語コードを含む&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_配置図&quot;&gt;配置図&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;開発マシン&quot; {
  artifact &quot;ソース&quot; {
    folder &quot;コンテンツ/&quot;
    folder &quot;テンプレート/&quot;
    folder &quot;assets/&quot;
  }

  component &quot;JBake CLI&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;ビルドサーバー
(CI/CD)&quot; {
  component &quot;GitHub Actions
または GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / ホスティング&quot; {
  node &quot;静的Webサーバー&quot; {
    artifact &quot;生成されたサイト&quot; {
      folder &quot;/fr/blog/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;生成されたサイト&quot; : déploiement

actor &quot;読者&quot; as users

users --&amp;gt; &quot;静的Webサーバー&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このアーキテクチャは、2つの言語でシンプルに始められ、大規模なリファクタリングなしに他の言語を追加することもできます。全体は完全に静的で高性能であり、JBakeの哲学に忠実です。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;良い多言語開発！ 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_導入&quot;&gt;導入&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_とその署名のダウンロード&quot;&gt;Tor とその署名のダウンロード&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_署名の暗号学的検証&quot;&gt;署名の暗号学的検証&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_tor_プロジェクトの公開鍵をインポートする&quot;&gt;1. Tor プロジェクトの公開鍵をインポートする&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_署名を確認&quot;&gt;2. 署名を確認&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_実践例有効な署名だが認証されていない鍵&quot;&gt;実践例：有効な署名だが、認証されていない鍵&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_署名を確認する理由は&quot;&gt;署名を確認する理由は？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_browser_の抽出と起動&quot;&gt;Tor Browser の抽出と起動&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ubuntu_デスクトップへの統合&quot;&gt;Ubuntu デスクトップへの統合&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_torを使って教育リソースを探索する&quot;&gt;Torを使って教育リソースを探索する&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_browserのアップデート&quot;&gt;Tor Browserのアップデート&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_参照&quot;&gt;参照&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_導入&quot;&gt;導入&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;デジタルプライバシーがますます脅かされる世界では、&lt;strong&gt;Tor Browser&lt;/strong&gt; は匿名性と情報の自由を守るために不可欠なツールのままです。 しかし、ダウンロードしたソフトウェアを、何も持たずに決して実行してはいけない&lt;strong&gt;その真正性を確認した&lt;/strong&gt;. この記事では、次のための包括的な方法を提示します：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tor Browser&lt;/strong&gt; とその署名をダウンロード`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ダウンロードしたファイルの有効性を確認する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntuで*Tor Browser*をインストールして起動する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;デスクトップメニューに追加して日常的に使用する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Torを介して教育リソースと倫理的OSINTを探索する&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_とその署名のダウンロード&quot;&gt;Tor とその署名のダウンロード&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor ブラウザ専用のフォルダーを作成してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次に、Torブラウザのアーカイブとその署名をダウンロードしてください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_署名の暗号学的検証&quot;&gt;署名の暗号学的検証&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このステップは&lt;strong&gt;不可欠&lt;/strong&gt;ダウンロードしたファイルが*Tor Project*のものであり、改ざんされていないことを確認するために。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_tor_プロジェクトの公開鍵をインポートする&quot;&gt;1. Tor プロジェクトの公開鍵をインポートする&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;キーが正しくインポートされていることを確認してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_署名を確認&quot;&gt;2. 署名を確認&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;すべてが正しければ、次のメッセージが表示されます：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;警告が未認証の鍵について表示される場合、これは単にTor Projectの信頼できる鍵にまだ署名していないだけで、署名は依然として有効です。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_実践例有効な署名だが認証されていない鍵&quot;&gt;実践例：有効な署名だが、認証されていない鍵&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;確認時にこのようなメッセージに遭遇することはよくあります：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このメッセージは、署名は技術的に「良い」（ファイルは変更されていない）ことを示していますが、GPGシステムは鍵自身への*信頼の証明*を行うことができません。この疑問を払拭するために、メイン鍵のフィンガープリントを比較することが不可欠です。 (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) Tor Projectの公式サイトに掲載されたものと&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;公式サイトによると、期待されるフィンガープリントは：&lt;code&gt;EF6E286DDA85EA2A4BA7DE684E2C6E8793298290&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;表示された足跡によって`gpg`公式サイトのものと*正確に*一致すれば、そのキーが正当でありファイルが安全であることを確信できます。「未認証のキー」の警告は、そのときはあなたのGPGローカル設定に関する情報であり、署名の有効性やファイルの真正性については関係ありません。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_署名を確認する理由は&quot;&gt;署名を確認する理由は？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;GPG署名の検証は、デジタルセキュリティにおける基本的な行為です。 次のことができます:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;保証する&lt;strong&gt;真正性&lt;/strong&gt;ダウンロードされたソフトウェア&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;悪意ある攻撃者によって侵害されたファイルのインストールを防止する&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;参加する&lt;strong&gt;デジタル主権&lt;/strong&gt;個人的な&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�責任ある倫理的なデジタル文化を促進する&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;ユーザー&quot; as U
actor &quot;TorProjectサーバー&quot; as S

usecase &quot;Tor とその署名をダウンロード&quot; as D
usecase &quot;公開鍵をインポート&quot; as K
usecase &quot;GPG署名を確認&quot; as V
usecase &quot;Torをインストールして起動&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_browser_の抽出と起動&quot;&gt;Tor Browser の抽出と起動&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ダウンロードしたアーカイブを解凍してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次にブラウザを起動してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;最初の起動時に、Torネットワークへの接続を確立するために設定ウィンドウが開きます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ubuntu_デスクトップへの統合&quot;&gt;Ubuntu デスクトップへの統合&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;アプリケーションメニューに &lt;strong&gt;Tor Browser&lt;/strong&gt; を追加 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;その後、&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;アプリケーションメニューから*Tor Browser*を起動&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ドックのお気に入りに追加&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;キーボードショートカットを作成する（希望する場合）&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_torを使って教育リソースを探索する&quot;&gt;Torを使って教育リソースを探索する&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Torは匿名化のためのツールだけではありません。 これは教育および研究資源へのアクセスポータルを構成し、特に次の分野において：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OSINT (オープンソースインテリジェンス)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;教育的な共有とオープンソース&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(アクセス via Tor でプライバシーを向上)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(Torを通じて閲覧可能)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(科学文献への自由アクセス)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;知識の伝達とデジタル社会における人間の理解&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;デジタル文化、表現の自由、知識へのアクセスに関するリソース&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;サイバーセキュリティと技術の倫理に関するオープンなドキュメンテーション&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_browserのアップデート&quot;&gt;Tor Browserのアップデート&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;最適なセキュリティを確保するために、&lt;strong&gt;Tor Browser&lt;/strong&gt; を最新の状態に保つことが重要です。このブラウザには自動アップデート機能が組み込まれており、コマンドラインからトリガーすることができます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor Browserのインストールディレクトリから、スタートスクリプトを再起動するだけです：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;起動時に、&lt;strong&gt;Tor Browser&lt;/strong&gt; は自動的に新しいバージョンが存在するかを確認します。存在する場合は、それをダウンロードしてインストールします。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このシンプルな方法は、常に最新のセキュリティパッチと最新の改善が適用されていることを保証します。これは、安全なブラウジングに不可欠です。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ダウンロードを確認することは、安全なデジタル環境で成長したいすべての人にとって必須の習慣です。 Torを検証済みの方法でインストールすることは&lt;strong&gt;デジタルの整合性を守る&lt;/strong&gt;, &lt;strong&gt;フリーソフトウェアへの信頼を保つ&lt;/strong&gt;, et &lt;strong&gt;情報自立性を強化する&lt;/strong&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;デジタルセキュリティは、 妄想ではなく、 良心に基づく行為である。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Torの使用の概要
actor Utilisateur
rectangle &quot;Tor ブラウザ&quot; {
rectangle &quot;匿名&quot; as A
rectangle &quot;OSINT調査&quot; as O
rectangle &quot;教育的な共有&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_参照&quot;&gt;参照&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Tor Projectの公式サイト:https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;署名検証ドキュメント：https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntuドキュメント：https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;教育的アーカイブ :https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この記事は、*セキュリティとデジタル意識*シリーズの一部です。 責任のある教育的な実践を促進することを目的とする フリーのツールを中心に&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_はじめに&quot;&gt;はじめに&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_バージョンカタログ_libs_versions_toml_リマインダー&quot;&gt;1. バージョンカタログ (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : リマインダー&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_問題複合ビルドと二つの別々な世界&quot;&gt;2. 問題：複合ビルドと二つの別々な世界&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_解決策依存関係の解決の共有&quot;&gt;3. 解決策:依存関係の解決の共有&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_結論適切に管理されたコンポジットビルドの力&quot;&gt;4. 結論：適切に管理されたコンポジットビルドの力&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_はじめに&quot;&gt;はじめに&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;対象ユーザー：マルチビルドプロジェクトでの依存関係管理に直面しているGradle開発者&lt;/div&gt;
&lt;p&gt;プラグインを作るための私たちの探求の中で`site-baker`私たちはクリーンで集中されたコードベースを維持しようと努めてきました。現代のGradleエコシステムにおけるベストプラクティスの一つは、の使用です&lt;strong&gt;バージョンカタログ&lt;/strong&gt; (&lt;code&gt;libs.versions.toml&lt;/code&gt;) で依存関係を管理するために。 しかし、プロジェクトがより複雑になるとどうなるでしょうか、例えば&lt;strong&gt;複合をビルド&lt;/strong&gt;ここで、独立したビルド（私たちのプラグイン）は他のものに含めなければなりませんか？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;そこが私たちの冒険が思いがけない転機を迎えた場所だった。私たちは私たちのプラグインが`site-baker`, それ自体が Gradle プロジェクトである、私たちのメインプロジェクトと同じバージョン カタログを使用します。 この記事は、私たちのシリーズの第五回目で、その課題をどのように解決したかを説明しています。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_バージョンカタログ_libs_versions_toml_リマインダー&quot;&gt;1. バージョンカタログ (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : リマインダー&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ファイル`gradle/libs.versions.toml`Gradleの機能で、プロジェクトの依存関係のバージョンと座標を一元管理することができます。通常、4つのセクションに構成されています：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]&lt;/code&gt;: バージョン番号のエイリアスを定義します (例:`kotlin = &quot;1.9.20&quot;`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]&lt;/code&gt;: 完全な依存関係のエイリアスを設定します。上で定義したバージョンを使用します（例:`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]`複数のライブラリを単一のエイリアスにグループ化（例：`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`[plugins]`Gradle プラグインのエイリアスを定義します。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;定義すると、Gradle は自動的に型付きアクセッサを生成し、これによりあなたの`build.gradle.kts`ずっと読みやすい :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;バージョン カタログのデータフロー&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;Gradle&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;によって読まれている&quot;
G --&amp;gt; BuildScript : &quot;アクセッサを生成 `libs&quot;
BuildScript -&amp;gt; G : &quot;libs` を使用して 依存関係を宣言する&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_問題複合ビルドと二つの別々な世界&quot;&gt;2. 問題：複合ビルドと二つの別々な世界&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちのプロジェクト構造は&lt;strong&gt;ビルド コンポジット&lt;/strong&gt;. 主要なプロジェクト (&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) プラグインのプロジェクトを含む (&lt;code&gt;site-baker&lt;/code&gt;) コマンド経由で`includeBuild(&quot;site-baker&quot;)&lt;code&gt;ファイルの中に`settings.gradle.kts&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;コンポジットビルドの構造&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
package &quot;主要プロジェクト&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;グレードル&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;プラグイン `site-baker` (Build Inclus)&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;サイトベーカー&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;問題は、デフォルトでは、インクルードされたビルドは&lt;strong&gt;別世界&lt;/strong&gt;. 自分固有の設定があり、自分固有のライフサイクルがあり、ファイルを見ません。&lt;code&gt;libs.versions.toml`メインビルドの。 私たちの`plugin/build.gradle.kts`使おうと試みていた`libs.plugins.kotlin.jvm&lt;/code&gt;, しかしオブジェクト`libs` n&amp;#8217;était pas généré à partir du bon fichier TOML, provoquant des erreurs de build.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_解決策依存関係の解決の共有&quot;&gt;3. 解決策:依存関係の解決の共有&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;何度か調べた結果、解決策はこのケースのために正確に設計されたGradleの機能であることがわかりました：&lt;code&gt;dependencyResolutionManagement&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ファイル内`settings.gradle.kts` du &lt;strong&gt;包括的な構築&lt;/strong&gt;(&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;), Gradleに使用するバージョンカタログの場所を伝えることができます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ここに、私たちが追加した設定に`site-baker/settings.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;重要な部分を分析しましょう：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)&lt;/code&gt;: 私たちは、エイリアスを通じてアクセスできるバージョンのカタログを宣言します。&lt;code&gt;libs&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))&lt;/code&gt;: これが魔法です。 私たちはGradleに、このカタログのソースがこのディレクトリ内にあるTOMLファイルであることを伝えます。&lt;code&gt;gradle&lt;/code&gt; du &lt;strong&gt;親プロジェクト&lt;/strong&gt;(&lt;code&gt;../&lt;/code&gt;“).”&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この設定では、ビルド`site-baker`彼は今、メインプロジェクトのバージョンカタログを使用しなければならないことを知っている。オブジェクト`libs`正しく生成され、依存関係は予定通りに解決されます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_結論適切に管理されたコンポジットビルドの力&quot;&gt;4. 結論：適切に管理されたコンポジットビルドの力&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この経験は多くの教訓を得るものでした。バージョンカタログは保守性に優れた素晴らしいツールですが、複合ビルドシナリオでのその動作は必ずしも直感的ではありません。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ポイントは、インクルードされたビルドでも独立したビルドのままであることを覚えておくことです。バージョンカタログのような設定を共有するには、Gradleが提供する明示的なメカニズム、例えばブロックを使用する必要があります。&lt;code&gt;dependencyResolutionManagement`中`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この問題を解決することで、私たちのビルドをきれいにするだけでなく、プラグインとメインプロジェクトが依存関係について唯一の真実のソースを共有することを確認することで、プロジェクトの一貫性も強化しました。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次の記事では、依存関係の管理が堅牢かつ集中化された今、さらに複雑なタスクを追加することでプラグインを充実させていきます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_導入&quot;&gt;導入&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_症状幽霊ビルド&quot;&gt;症状：幽霊ビルド&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_調査構成キャッシュとは何ですか&quot;&gt;調査：構成キャッシュとは何ですか？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_問題の原因_適合していないプラグイン&quot;&gt;問題の原因: 適合していないプラグイン&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_一時的なソリューションキャッシュを無効にする&quot;&gt;一時的なソリューション：キャッシュを無効にする&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_真の解決策プラグインを互換性を持たせる&quot;&gt;真の解決策：プラグインを互換性を持たせる&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_導入&quot;&gt;導入&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;対象 : すでに &quot;magiques&quot; または予期しないビルドの挙動に遭遇した Gradle 開発者&lt;/div&gt;
&lt;p&gt;私たちのプラグイン作成の冒険で`site-baker`, 我々は TDD を厳格に実践しました。各機能はテストされ、検証され、そして我々は確信を持って進んでいきました。そしてある日、予期せぬことが起こりました。ビルドは予測不能な動作を始めました。プラグインのロジックや設定ファイルの変更が無視されているかのように見え、かつて信頼できた機能テストも理由もなく失敗し始めました。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この種の問題は信じがたいほどイライラさせることがあります。これはツールの信頼性と私たちのコードの妥当性を疑問視します。激しいデバッグセッションの後、犯人が特定されました：その&lt;strong&gt;Gradleの設定キャッシュ&lt;/strong&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_症状幽霊ビルド&quot;&gt;症状：幽霊ビルド&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;問題は様々な形で現れていた：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;タスク内の文字列を編集していた`println`, しかし古い文字列は実行時に表示され続けた。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ファイルの中で値を変更していた。`managed-jbake-context.yml`しかし、プラグインはファイルが変更されていないかのように振る舞った。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;機能テストは、その場でテストプロジェクトを作成するものですが、プラグインが新しく作成された設定ファイルを検出しているようには見えず、失敗していました。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;まるで Gradle が私たちのビルドの「幽霊バージョン」を実行しているかのように、すべてが進行していました。最新の変更を無視して。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_調査構成キャッシュとは何ですか&quot;&gt;調査：構成キャッシュとは何ですか？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;構成キャッシュは、比較的新しい機能であり、Gradleの非常に強力な機能です。新しいバージョンではデフォルトで有効になっています。その目的は、ビルドをより速くすることです。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;原理は単純です：&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;最初の実行時に、Gradle は フェーズ を実行します&lt;strong&gt;設定&lt;/strong&gt;(の読み取り`build.gradle.kts`, タスクの作成, 依存関係の解決) と タスクグラフを構築します。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;このフェーズの終わりに、Gradle&lt;strong&gt;このタスクグラフをシリアライズして&lt;/strong&gt;そしてそれをキャッシュに保存します。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;次の実行時に何も変更されていない場合（ビルドスクリプトが,&lt;code&gt;gradle.properties&lt;/code&gt;, など), Gradle&lt;strong&gt;設定フェーズを完全にスキップする&lt;/strong&gt;そしてキャッシュされたタスクグラフを再利用します。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;大規模なプロジェクトでは時間の節約が驚くほど顕著です。ただし、このパフォーマンスにはコストが伴います：プラグインの記述方法に厳格なルールを課します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;構成キャッシュのライフサイクル&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_問題の原因_適合していないプラグイン&quot;&gt;問題の原因: 適合していないプラグイン&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちのプラグイン`site-baker`無意識のうちに、設定キャッシュのいくつかのルールを違反していた。タスクグラフがシリアライズ可能であるためには、タスクはオブジェクトなどの複雑なオブジェクトへの参照を含んではならない。`Project`または、実行フェーズ中に任意のファイルを読み込むことができます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちの主な間違いは、タスクの実行ロジック内でYAMLファイルの内容を直接読み込んでいたことです。これは、拡張機能に保存されているパスへの参照を使用して行われました。このアプローチは、この読み込みがモデル化されていないような場合、Gradleがファイルの内容が変更されたかどうかを知ることができないため、キャッシュと互換性がありません。&lt;strong&gt;タスクエントリ&lt;/strong&gt; (Task Input).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_一時的なソリューションキャッシュを無効にする&quot;&gt;一時的なソリューション：キャッシュを無効にする&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちのブロックを解除し、予測可能なビルド動作を取り戻すために、最も速い方法は設定キャッシュを無効にすることでした。ファイルに以下の行を追加するだけです`gradle.properties`プラグインを使用しているプロジェクト（または私たちの場合、テストプロジェクト）の`site-baker`).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;瞬時に、ビルドは通常の動作を取り戻しました。各実行が構成フェーズを再起動し、私たちの変更が考慮されました。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ただし、これは回避策であり、持続可能な解決策ではありません。パフォーマンスを犠牲にし、プラグインの根本的な問題を解決しません。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_真の解決策プラグインを互換性を持たせる&quot;&gt;真の解決策：プラグインを互換性を持たせる&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;プラグインが現代のGradleエコシステムの良い市民であるためには、設定キャッシュと互換性がある必要があります。これは、データがタスクに流れる方法を見直すことを意味します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;キーはそれらを使うことです&lt;strong&gt;プロバイダーのAPI&lt;/strong&gt;Gradleの。 直接の値を渡す代わりに（例えば`String` ou un &lt;code&gt;File&lt;/code&gt;) 私たちのタスクに対して、私たちは何かを通過しなければならない`Property&amp;lt;T&amp;gt;`または`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;以下はリファクタリング計画です：&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;タスクエントリを宣言する :&lt;/strong&gt;YAMLファイルをパースするタスクは、このファイルを入力として宣言しなければなりません。そのためにアノテーションを使用します。&lt;code&gt;@InputFile&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] python&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_導入&quot;&gt;導入&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_コンテキスト_私たちのプラグイン_site_baker&quot;&gt;1. コンテキスト: 私たちのプラグイン `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_kotlin_での設定のモデリング&quot;&gt;2. Kotlin での設定のモデリング&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_jacksonのbuild_gradle_ktsへの統合&quot;&gt;3. Jacksonの`build.gradle.kts`への統合&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_tddアプローチyamlパースのテスト&quot;&gt;4. TDDアプローチ：YAMLパースのテスト&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_単体テスト_yamlをkotlinオブジェクトにマッピング&quot;&gt;4.1. 単体テスト: YAMLをKotlinオブジェクトにマッピング&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_機能テスト構成ファイルの読み取りを検証する&quot;&gt;4.2. 機能テスト：構成ファイルの読み取りを検証する&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_パースフローの可視化&quot;&gt;5. パースフローの可視化&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_導入&quot;&gt;導入&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;対象 : 中級 Gradle 開発者で、複雑な設定を管理したい人&lt;/div&gt;
&lt;p&gt;Gradleプラグインの開発において、複雑な構成の管理は一般的な作業です。DSLに数百のプロパティを詰め込むのではなく、外部ファイル、例えばYAMLに設定を定義するほうが、すっきりしており保守しやすいことが多いです。この記事では、強力なJacksonライブラリを使ってYAMLファイルをKotlinオブジェクトにパースする統合方法を、厳格なTDDアプローチを採用してプラグインの堅牢性を確保する形でガイドします。&lt;code&gt;site-baker&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_コンテキスト_私たちのプラグイン_site_baker&quot;&gt;1. コンテキスト: 私たちのプラグイン `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちのプラグイン`site-baker`は、静的サイトの生成とデプロイを自動化するように設計されています。YAML設定ファイルを読み込む必要があります (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) ソースのパス、デプロイ先、Gitの識別子などの情報を取得するために。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;パースしたいYAML設定はこのようになります：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_kotlin_での設定のモデリング&quot;&gt;2. Kotlin での設定のモデリング&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;パースする前に、Kotlinでデータの構造を定義する必要があります。Jacksonはこれらのクラスを使用してYAMLコンテンツを自動的にマッピングします。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;機能`parseSiteConfiguration`これはデシリアライズのエントリーポイントです。使用します`ObjectMapper`Jacksonの、設定済みの`YAMLFactory`YAMLフォーマットに対して`registerKotlinModule()`Kotlinの特殊機能のサポート（例えばプロパティのデフォルト値など）のため。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_jacksonのbuild_gradle_ktsへの統合&quot;&gt;3. Jacksonの`build.gradle.kts`への統合&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Jacksonを使用するには、必要な依存関係を追加する必要がありますの`build.gradle.kts`私たちのモジュールの`plugin`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちは使用します`jackson-module-kotlin`Kotlinのサポートのためにおよび`jackson-dataformat-yaml`YAML形式の管理のために。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_tddアプローチyamlパースのテスト&quot;&gt;4. TDDアプローチ：YAMLパースのテスト&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;今、TDDを適用してパースロジックを検証しましょう。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_単体テスト_yamlをkotlinオブジェクトにマッピング&quot;&gt;4.1. 単体テスト: YAMLをKotlinオブジェクトにマッピング&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちは単体テストで始めます`SiteBakerPluginTest.kt`関数が機能しているかを確認するために`parseSiteConfiguration`YAML文字列をオブジェクトに正しく変換できます`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このテストはファイルの内容を読み込みます`managed-jbake-context.yml`(テストが有効であるために存在しなければならない)およびオブジェクトに対するアサーションを実行する`SiteConfiguration`結果として。 YAML のキーの値が正しくマッピングされていることを検証します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_機能テスト構成ファイルの読み取りを検証する&quot;&gt;4.2. 機能テスト：構成ファイルの読み取りを検証する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;プラグインがそのDSLを通じて設定ファイルを読み取ることができ、実際のGradle環境でパースが機能することを確認するために、私たちは機能テストを追加します`SiteBakerPluginFunctionalTest.kt`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このテストは重要です。なぜなら、実際のプロジェクトでのプラグインの実行をシミュレートするからです。これが必要です&lt;strong&gt;密閉&lt;/strong&gt;, すなわち彼は自分でファイルを作成しなければならない`managed-jbake-context.yml`制御されたコンテンツを使用して、テストの再現性と隔離を保証します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この機能テストは、テストの一時ディレクトリにコピーされた設定ファイルに期待されるデータが含まれていることを確認します。このテストは直接 YAML を Kotlin オブジェクトにパースしませんが、ファイルとその内容の存在を検証し、これはプラグインによるパースに必要な前提条件となります。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_パースフローの可視化&quot;&gt;5. パースフローの可視化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次の図は、YAML 設定のパース時のデータフローとインタラクションを示しています：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Gradle ユーザー&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;SiteBakerPlugin&quot; as Plugin
participant &quot;サイトエクステンション&quot; as Extension
participant &quot;managed-jbake-context.yml&quot; as ConfigFile
participant &quot;parseSiteConfiguration()&quot; as Parser
participant &quot;SiteConfiguration ( Kotlin オブジェクト )&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDDのアプローチを取ることで、Jacksonライブラリを使用してYAML設定ファイルをKotlinオブジェクトにパースし、Gradleプラグインに正常に組み込むことができました。この方法により、以下のことが可能になりました：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;明確にモデリング&lt;/strong&gt;私たちの構成とKotlinのデータクラス。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;パースロジックを検証する&lt;/strong&gt;対象となる単体テストで。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;統合の確保&lt;/strong&gt;実際の Gradle 環境で、密閉された機能テストにより。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この堅固な基盤により、この設定に基づく機能でプラグインを拡張する大きな自信を得られ、コードの保守性と堅牢性も確保できます。YAMLのパースは今ではプラグインの信頼性が高くテスト済みの機能となっています。&lt;code&gt;site-baker&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_プロジェクトの初期化&quot;&gt;プロジェクトの初期化&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_私たちの最初のtddサイクル_タスクを記録する&quot;&gt;2. 私たちの最初のTDDサイクル : タスクを記録する&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_まずテストする_失敗するテスト&quot;&gt;2.1. まずテストする (失敗するテスト)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_コードの次に_テストを通す&quot;&gt;2.2. コードの次に (テストを通す)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_第2サイクル_tdd_dsl拡張を追加&quot;&gt;3. 第2サイクル TDD : DSL拡張を追加&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_最初のテスト&quot;&gt;3.1. 最初のテスト&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_コードその後&quot;&gt;3.2. コードその後&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_機能テスト統合の検証&quot;&gt;4. 機能テスト：統合の検証&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_統合テスト_制御された環境を作成する&quot;&gt;4.1. 統合テスト : 制御された環境を作成する&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_ロジックを最終化する&quot;&gt;4.2. ロジックを最終化する&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この記事では、(TDD - テスト駆動開発) アプローチを使用して、Gradleプラグインのための堅牢な開発基盤を構築する方法について探ります。 この方法により、私たちのコードが堅牢で保守しやすく、最初から正確に要件を満たすことが保証されます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_プロジェクトの初期化&quot;&gt;プロジェクトの初期化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradleはコマンドを使うことで新しいプラグインの作成を大いに容易にします。&lt;code&gt;gradle init&lt;/code&gt;. &quot;Gradle Plugin&quot;をKotlinで作成することを選択すると、すぐに使えるプロジェクト構造が得られ、その中には2種類の重要なテストが含まれます：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;単体テスト :&lt;/strong&gt;位置している`src/test`, これらは、私たちのプラグインの孤立したコンポーネントを検証することを可能にします。たとえば、タスクの内部ロジックや拡張機能の設定などです。これらは高速であり、Gradle の完全な実行を必要としません。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;機能テスト :&lt;/strong&gt;にある`src/functionalTest`, 彼らは使う`GradleRunner`一時的なテストプロジェクトで完全なGradleビルドを実行するために。これにより、制御された環境でプラグインの実際の動作を確認できます。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_私たちの最初のtddサイクル_タスクを記録する&quot;&gt;2. 私たちの最初のTDDサイクル : タスクを記録する&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちの最初の要件はシンプルです：プラグインは、名前が付けられたタスクを記録する必要があります`printSiteConfig`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_まずテストする_失敗するテスト&quot;&gt;2.1. まずテストする (失敗するテスト)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDDに従い、まず、このタスクの存在を確認するテストを書きます。 では`SiteBakerPluginTest.kt`(私たちのユニットテストファイル)、追加します：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このテストが失敗するのは、私たちがまだプラグインにコードを書いていないからです。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_コードの次に_テストを通す&quot;&gt;2.2. コードの次に (テストを通す)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;今、私たちは必要最小限のコードを書いています`SiteBakerPlugin.kt`テストが通るように :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;テストを再実行し、合格しています。最初の機能は検証されています。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_第2サイクル_tdd_dsl拡張を追加&quot;&gt;3. 第2サイクル TDD : DSL拡張を追加&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次の要件は、ユーザーがDSLブロックを使って私たちのプラグインを設定できるようにすること`build.gradle.kts`. 私たちはブロックが欲しい`site { &amp;#8230;&amp;#8203; }`設定パスを指定できる場所。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_最初のテスト&quot;&gt;3.1. 最初のテスト&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;�拡張機能が正しく動作することを確認するためのテストを追加しています。`site`よく記録されており、そこに値を割り当てることができる。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このテストは失敗しますなぜならクラスが`SiteExtension`拡張機能の登録も存在しない&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_コードその後&quot;&gt;3.2. コードその後&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;私たちはクラスを作ります`SiteBakerExtension.kt`と私たちは更新します`SiteBakerPlugin.kt`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;テストが再びパスしました。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_機能テスト統合の検証&quot;&gt;4. 機能テスト：統合の検証&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ユニットのテストが終わった今、実際のビルドですべてが正しく連携することを確認する必要があります。これは機能テストの役割です。[something]における`SiteBakerPluginFunctionalTest.kt`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_統合テスト_制御された環境を作成する&quot;&gt;4.1. 統合テスト : 制御された環境を作成する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このテストは、私たちのプラグインを使用した実際のプロジェクトをシミュレートします。信頼性を持たせるために、これはでなければなりません。&lt;strong&gt;気密&lt;/strong&gt;,つまり、システム上に存在するファイルに依存してはならない。必要となる実行条件はすべて自分自身で作らなければならない。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;テストはしたがって：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;作る`build.gradle.kts`私たちのプラグインとそのDSLを使用するテスト。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;設定ファイルを作成&lt;/strong&gt;(&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) プラグインが読み込むべきものです。これはテストの堅牢性にとって重要なステップです。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;タスクの実行`printSiteConfig`経由して`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ビルドの出力が正しいことを確認する。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この構成ファイルを実行のたびにコピーまたは作成することで、テストが&lt;strong&gt;再現可能&lt;/strong&gt;外部の状態に依存せず。これによりファイルの読み込みに関連する可能性のある回帰から私たちのテストを守ります。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このテストはタスクが続く間失敗します`printSiteConfig`拡張機能の値を実際には使用しません。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_ロジックを最終化する&quot;&gt;4.2. ロジックを最終化する&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;タスクを更新しています中で`SiteBakerPlugin.kt`設定された値を表示するために：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;すべてのテスト（単体テストおよび機能テスト）は、今ではパスしています。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDDアプローチに従い、私たちはインクリメンタルかつ安全にプラグインを構築しました。各小さな機能は、すぐにテストによって検証されます。高速なユニットテストから、完全な統合を検証する機能テストまでです。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;テストを機能的にするために注意を払って&lt;strong&gt;気密の&lt;/strong&gt;— 必要な構成ファイルをプログラムで作成することで — 私たちは極めて強固な安全ネットを築きます。この厳格さは、回帰を効果的に防ぎ、その後、YAML構成ファイルのパースなど、より複雑な機能を追加する際に大きな自信を与えてくれます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この堅牢なテスト基盤は、プラグインの保守および将来の進化において最も貴重な資産です。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_はじめに&quot;&gt;はじめに&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ステップ_1_プロジェクト_アシスタントを起動する&quot;&gt;ステップ 1 : プロジェクト アシスタントを起動する&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ステップ_2_生成された構造を理解する&quot;&gt;ステップ 2 : 生成された構造を理解する&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_重要なファイルとフォルダー&quot;&gt;重要なファイルとフォルダー&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_はじめに&quot;&gt;はじめに&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;対象: 初心者から中級者までの Gradle 開発者&lt;/div&gt;
&lt;p&gt;Gradleプラグインの新しいプロジェクトを始めることは恐ろしく見えるかもしれません。幸いなことに、Gradleは強力なインタラクティブなアシスタントを提供します、そのタスクは`init`, このツールは完全で綺麗かつすぐに使えるプロジェクト構造を生成します。このガイドでは、このツールを使って健全なプラグインベースを作成する方法、構造を説明し、そして最初のビルドタスクを実行する方法を示します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ステップ_1_プロジェクト_アシスタントを起動する&quot;&gt;ステップ 1 : プロジェクト アシスタントを起動する&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;コマンド`gradle init`これは出発点です。これにより、プロジェクトを設定するための質問を一連行うコマンドラインアシスタントが起動されます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;空のフォルダーでターミナルを開き、次のコマンドを実行してください：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;アシスタントが案内します。Kotlin で書かれた Gradle プラグインの選択肢は次の通りです：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;生成するプロジェクトの種類を選択:&lt;/strong&gt;選んでください`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;実装言語を選択:&lt;/strong&gt;選んでください`Kotlin`。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ビルドスクリプトDSLを選択:&lt;/strong&gt;選んでください`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;プロジェクト名:&lt;/strong&gt;プロジェクトの名前を入力してください（例：&lt;code&gt;site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;プラグイン ID:&lt;/strong&gt;あなたのプラグインに一意の識別子を付けてください (例：&lt;code&gt;com.cheroliv.site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;プラグインクラス:&lt;/strong&gt;実装クラスの名前を指定してください（例:`com.cheroliv.SiteBakerPlugin`).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;完了すると、Gradleは完全なファイルツリーを生成します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;初期化プロセスの図&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Lancer `gradle init`;
:Choisir &quot;Gradle プラグイン&quot;;
:Choisir &quot;コトリン&quot; (langage);
:Choisir &quot;コトリン&quot; (DSL);
:Saisir nom, ID, et classe;
:Projet généré;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ステップ_2_生成された構造を理解する&quot;&gt;ステップ 2 : 生成された構造を理解する&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;アシスタントはマルチモジュールのプロジェクト構造を作成し、ルートプロジェクトをプラグインのソースコードから分離します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_重要なファイルとフォルダー&quot;&gt;重要なファイルとフォルダー&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts&lt;/code&gt;: このルートにあるファイルは、ビルドに含まれるモジュールを定義します。ここでは、サブプロジェクトを含みます。&lt;code&gt;plugin&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_導入&quot;&gt;導入&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_jdk_gradleエンジン&quot;&gt;1. JDK: Gradleエンジン&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_どのバージョンを選びますか&quot;&gt;どのバージョンを選びますか？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkman_を介したインストール_推奨&quot;&gt;SDKMAN! を介したインストール (推奨)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkmanをインストール&quot;&gt;&lt;strong&gt;SDKMAN!をインストール&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jdk_のバージョンをインストールする&quot;&gt;JDK のバージョンをインストールする&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_インストールを確認&quot;&gt;インストールを確認&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ide_intellij_idea&quot;&gt;2. IDE : IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle_ビルドツール&quot;&gt;3. Gradle : ビルドツール&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkmanによるインストール&quot;&gt;SDKMAN!によるインストール&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_gradleをインストールする&quot;&gt;Gradleをインストールする&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_インストールを確認する&quot;&gt;インストールを確認する&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_静的サイトジェネレーター&quot;&gt;4. JBake : 静的サイトジェネレーター&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkman_を使ったインストール&quot;&gt;SDKMAN! を使ったインストール&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_jbakeをインストール&quot;&gt;JBakeをインストール&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_インストールを確認_2&quot;&gt;インストールを確認&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_gradleラッパー絶対的なベストプラクティス&quot;&gt;5. Gradleラッパー：絶対的なベストプラクティス&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_と_portainer_再現可能なビルド_オプション&quot;&gt;6. Docker と Portainer : 再現可能なビルド (オプション)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_docker_engineのインストール&quot;&gt;Docker Engineのインストール&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerを公式スクリプトでインストール&quot;&gt;&lt;strong&gt;Dockerを公式スクリプトでインストール：&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerをsudoなしで管理する推奨&quot;&gt;&lt;strong&gt;Dockerを`sudo`なしで管理する（推奨）：&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_portainer_gui_を使って_docker_を管理&quot;&gt;Portainer (GUI) を使って Docker を管理&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_portainerのデータ用ボリュームを作成してください&quot;&gt;Portainerのデータ用ボリュームを作成してください：&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_portainer_コンテナーを起動&quot;&gt;&lt;strong&gt;Portainer コンテナーを起動：&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_導入&quot;&gt;導入&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;対象者 : Gradle プラグインの作成に取り組みたい開発者&lt;/div&gt;
&lt;p&gt;Gradleプラグインを効率的に開発するためには、適切に設定された開発環境が不可欠です。 良いセットアップは時間を節約し、フラストレーションを減らし、ビルドの一貫性を確保します。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;このガイドは4つの重要な柱に焦点を当てています：&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Le &lt;strong&gt;JDK&lt;/strong&gt;(Java Development Kit)、なぜならGradleとJBakeはJVM上で実行されます。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Un &lt;strong&gt;統合開発環境&lt;/strong&gt;モダンな(IntelliJ IDEA)で、KotlinとGradleのサポートが良い。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gradle&lt;/strong&gt;自身で、プロジェクトを初期化するために。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;JBake&lt;/strong&gt;, 私たちの静的サイトのエンジン。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;開発環境のコンポーネント&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
node &quot;開発者の機械&quot; {
  component &quot;JDK (JVM)&quot; as JDK
  component &quot;IntelliJ IDEA&quot; as IDE
  component &quot;Gradle (グローバル)&quot; as Gradle
  component &quot;JBake (グローバル)&quot; as JBake

  IDE --&amp;gt; JDK : utilise
  Gradle --&amp;gt; JDK : utilise
  JBake --&amp;gt; JDK : utilise
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_jdk_gradleエンジン&quot;&gt;1. JDK: Gradleエンジン&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle は Java 仮想マシン (JVM) 上で実行されるアプリケーションです。 したがって、JDKのインストールは絶対に必要な前提条件です。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_どのバージョンを選びますか&quot;&gt;どのバージョンを選びますか？&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JavaのLTS(Long-Term Support)バージョンを使用することをお勧めします。 現在,&lt;strong&gt;JDK 17&lt;/strong&gt; ou &lt;strong&gt;JDK 21&lt;/strong&gt;非常に良い選択肢です。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sdkman_を介したインストール_推奨&quot;&gt;SDKMAN! を介したインストール (推奨)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;SDKMAN!は、JavaやGradleを含む多数のSDKのバージョンを管理するための優れたツールです。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_sdkmanをインストール&quot;&gt;&lt;strong&gt;SDKMAN!をインストール&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -s &quot;https://get.sdkman.io&quot; | bash source &quot;$HOME/.sdkman/bin/sdkman-init.sh&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_jdk_のバージョンをインストールする&quot;&gt;JDK のバージョンをインストールする&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Pour lister les versions de Java disponibles sdk list java

# Pour installer Java 17 (par exemple, la distribution Temurin)
sdk install java 17.0.8-tem&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_インストールを確認&quot;&gt;インストールを確認&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;java -version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;インストールしたばかりのバージョンが表示されるはずです。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_ide_intellij_idea&quot;&gt;2. IDE : IntelliJ IDEA&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle プラグインの開発に Kotlin DSL を使用して&lt;strong&gt;IntelliJ IDEA&lt;/strong&gt;選択のツールです。 Gradle と Kotlin との統合は比類ない。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;コミュニティエディション :&lt;/strong&gt;無料で、開始するには十分すぎるほどです。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;アルティメットエディション：&lt;/strong&gt;有料です。ウェブ開発とデータベースのための高度な機能を提供します。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JetBrainsのサイトからご自身に合ったバージョンをダウンロードしてください：https://www.jetbrains.com/idea/download/&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;IDEは自動的にあなたのファイルを検出します`build.gradle.kts` et &lt;code&gt;settings.gradle.kts&lt;/code&gt;, 強力な自動補完、コードナビゲーション、統合されたデバッグツールを提供します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_gradle_ビルドツール&quot;&gt;3. Gradle : ビルドツール&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;各プロジェクトがGradle Wrapperを通じて自身のGradleバージョンを使用する場合でも、新しいプロジェクトの初期化などのタスクのためにグローバルなGradleのインストールがあると便利です (&lt;code&gt;gradle init&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sdkmanによるインストール&quot;&gt;SDKMAN!によるインストール&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JDKのように、SDKMAN!はGradleのインストールを簡単にします。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_gradleをインストールする&quot;&gt;Gradleをインストールする&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install gradle&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_インストールを確認する&quot;&gt;インストールを確認する&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このコマンドは、使用されている Gradle、Kotlin、Groovy、および JDK のバージョンを表示します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_jbake_静的サイトジェネレーター&quot;&gt;4. JBake : 静的サイトジェネレーター&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBakeは、私たちがソースファイル（このファイルのように）を静的なウェブサイトに変換するために使用するツールです。 ローカルにインストールしておくと、変更のプレビューが便利です。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sdkman_を使ったインストール&quot;&gt;SDKMAN! を使ったインストール&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;他のツールと同様に、SDKMAN! が最もシンプルな方法です。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_jbakeをインストール&quot;&gt;JBakeをインストール&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install jbake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_インストールを確認_2&quot;&gt;インストールを確認&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;jbake -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このコマンドはJBakeのバージョンと、それが使用するJava環境の情報を表示します。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_gradleラッパー絶対的なベストプラクティス&quot;&gt;5. Gradleラッパー：絶対的なベストプラクティス&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;プロジェクトを作成したら（これは次の記事で説明します）、もうグローバルコマンドを使用すべきではありません`gradle`。 代わりに、あなたはそれを使います&lt;strong&gt;Gradleラッパー&lt;/strong&gt;(&lt;code&gt;./gradlew&lt;/code&gt;), あなたのプロジェクトに組み込まれたスクリプト。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;なぜ？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;再現性：&lt;/strong&gt;ラッパーは、プロジェクトで作業しているすべての人（CI/CDサーバーを含む）が正確に同じものを使用することを保証します。&lt;strong&gt;同じバージョンのGradle&lt;/strong&gt;, これにより異なる環境によるビルドエラーが解消されます。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;シンプルさ：&lt;/strong&gt;プロジェクトに貢献するためにGradleを手動でインストールする必要はありません。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;リポジトリをクローンして実行するだけ`./gradlew`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;典型的なコマンドはこのように：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Ne pas faire : gradle build
# À faire :
./gradlew build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_6_docker_と_portainer_再現可能なビルド_オプション&quot;&gt;6. Docker と Portainer : 再現可能なビルド (オプション)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;プラグインを書く上で厳密に必要というわけではないが、Docker と Portainer はモダンな DevOps ツールであり、再現可能なビルドの作成と環境の管理を大幅に容易にします。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_docker_engineのインストール&quot;&gt;Docker Engineのインストール&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dockerを使うと、アプリケーションとその依存関係をコンテナにパッケージングできます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_dockerを公式スクリプトでインストール&quot;&gt;&lt;strong&gt;Dockerを公式スクリプトでインストール：&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -fsSL https://get.docker.com -o get-docker.sh sudo sh get-docker.sh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_dockerをsudoなしで管理する推奨&quot;&gt;&lt;strong&gt;Dockerを`sudo`なしで管理する（推奨）：&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;あなたのユーザーをグループに追加してください`docker`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo usod -aG docker $USER&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;

&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run hello-world&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_portainer_gui_を使って_docker_を管理&quot;&gt;Portainer (GUI) を使って Docker を管理&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Portainerは、Dockerコンテナを管理するための軽量なウェブインターフェース。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_portainerのデータ用ボリュームを作成してください&quot;&gt;Portainerのデータ用ボリュームを作成してください：&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker volume create portainer_data&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_portainer_コンテナーを起動&quot;&gt;&lt;strong&gt;Portainer コンテナーを起動：&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run -d -p 8000:8000 -p 9443:9443 --name portainer --restart=always -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer-ce:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;あなたは今、Portainerのインターフェースにアクセスできます`https://localhost:9443`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;あなたの環境は今準備が整いました！ JDK、最適なIDE、Gradle、JBakeを持っています。 Dockerを追加すると、コンテナ化された再現可能なビルドを作成する準備も整います。 このしっかりした基盤があれば、本質に集中できます：強力で便利なプラグインの開発に。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;次の記事では、そのコマンドを使用します。`gradle init`私たちの最初のプラグインプロジェクトの構造を生成するために。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_poetry_との統合&quot;&gt;Poetry との統合&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_poetryのインストール&quot;&gt;Poetryのインストール&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_プロジェクトの初期化&quot;&gt;プロジェクトの初期化&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_依存関係の追加とインストール&quot;&gt;依存関係の追加とインストール&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_poetryを使った公開&quot;&gt;Poetryを使った公開&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerを使った再現可能なビルド&quot;&gt;Dockerを使った再現可能なビルド&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerfileの例&quot;&gt;Dockerfileの例&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_github_actionsへの統合&quot;&gt;GitHub Actionsへの統合&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_条件付き公開&quot;&gt;条件付き公開&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_renovate_と_dependabot_を使った依存関係の自動化&quot;&gt;Renovate と Dependabot を使った依存関係の自動化&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dependabot&quot;&gt;Dependabot&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_リノベート&quot;&gt;リノベート&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_plantuml図&quot;&gt;PlantUML図&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ユースケース_高度なcicd&quot;&gt;ユースケース – 高度なCI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_シーケンス_条件付き公開&quot;&gt;シーケンス – 条件付き公開&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ステータス_cicd_パイプライン&quot;&gt;ステータス – CI/CD パイプライン&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_デプロイメント_cicdアーキテクチャ&quot;&gt;デプロイメント – CI/CDアーキテクチャ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_結論&quot;&gt;結論&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このシリーズの最初の2つの部分では、私たちは： - GitHub Actions と PyPI を使用して Python アプリケーションの機能的な CI/CD パイプラインを構築しました。 - このパイプラインをマルチバージョンテスト、Test PyPIによる段階的リリース、品質およびセキュリティツールで工業化しました。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この第三部では、私たちは行きます&lt;strong&gt;PyPI への単なる公開を超えて&lt;/strong&gt;を構築するために、完全で堅牢かつプロフェッショナルな CI/CD チェーンを作るために : - &lt;strong&gt;詩&lt;/strong&gt;モダンなパッケージングと依存関係の最適化された管理のために - &lt;strong&gt;ドッカー&lt;/strong&gt;再現可能でマルチプラットフォームなビルドを作成するために。 - &lt;strong&gt;条件付き出版&lt;/strong&gt;リリース候補などのシナリオを管理するために - &lt;strong&gt;自動化ツール&lt;/strong&gt;(Renovate, Dependabot) パイプラインを最新の状態に保つために労力をかけずに。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_poetry_との統合&quot;&gt;Poetry との統合&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry は従来のパッケージングツール (setup.py, requirements.txt) を置き換え、依存関係とビルドの管理を一元化する中に`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_poetryのインストール&quot;&gt;Poetryのインストール&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Installer Poetry
curl -sSL https://install.python-poetry.org | python3 -
# Vérifier la version
poetry --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_プロジェクトの初期化&quot;&gt;プロジェクトの初期化&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Initialiser un nouveau projet avec Poetry
poetry init
# Suivre l&#39;assistant pour renseigner : nom, version, description, licence, dépendances.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;これはファイルを生成します`pyproject.toml`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-toml hljs&quot; data-lang=&quot;toml&quot;&gt;[tool.poetry]
name = &quot;playlist-downloader&quot;
version = &quot;0.1.0&quot;
description = &quot;CLI tool for managing YouTube playlists&quot;
authors = [&quot;Christophe Hérolivier &amp;lt;cheroliv@example.com&amp;gt;&quot;]

[tool.poetry.dependencies]
python = &quot;&amp;gt;=3.8&quot;
typer = &quot;^0.9.0&quot;
yt-dlp = &quot;^2023.7.6&quot;
google-api-python-client = &quot;^2.0.0&quot;
google-auth-oauthlib = &quot;^1.0.0&quot;

[tool.poetry.group.dev.dependencies]
pytest = &quot;^7.0&quot;
mypy = &quot;^1.0&quot;
bandit = &quot;^1.7&quot;
safety = &quot;^2.3&quot;
black = &quot;^23.0&quot;
ruff = &quot;^0.1&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_依存関係の追加とインストール&quot;&gt;依存関係の追加とインストール&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;poetry add typer yt-dlp google-api-python-client google-auth-oauthlib
poetry add --group dev pytest mypy black bandit safety ruff&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_poetryを使った公開&quot;&gt;Poetryを使った公開&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry はネイティブに公開を管理します :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Publication sur Test PyPI
poetry publish --build --repository test-pypi

# Publication sur PyPI
poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このコマンドは自動的に存在する情報を使用する`pyproject.toml`。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dockerを使った再現可能なビルド&quot;&gt;Dockerを使った再現可能なビルド&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;開発、CI/CD、本番で同じ実行を保証するために、DockerはPoetryと完全に統合されます。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dockerfileの例&quot;&gt;Dockerfileの例&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-dockerfile hljs&quot; data-lang=&quot;dockerfile&quot;&gt;FROM python:3.11-slim

WORKDIR /app
COPY pyproject.toml poetry.lock ./
RUN pip install poetry
RUN poetry install --no-root --only main

COPY . .

CMD [&quot;poetry&quot;, &quot;run&quot;, &quot;python&quot;, &quot;cli.py&quot;]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;これは保証します： - 凍結されたPython環境。 経由でロックされた依存関係`poetry.lock`. - Dockerをサポートするあらゆるシステムで実行可能なイメージ。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_github_actionsへの統合&quot;&gt;GitHub Actionsへの統合&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;name: Docker Build

on:
  push:
    branches: [main]

jobs:
  build-docker:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Build Docker image
        run: docker build -t ghcr.io/${{ github.repository }}:latest .
      - name: Push Docker image
        run: docker push ghcr.io/${{ github.repository }}:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_条件付き公開&quot;&gt;条件付き公開&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;プロフェッショナルなパイプラインでは、特定の場合のみ公開できる必要があります : - テストPyPI向けリリース候補。 - 安定版をPyPIに - Builds Docker トリガーのみ`main`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;- name: Publish to Test PyPI
  if: contains(github.ref, &#39;-rc&#39;)
  run: poetry publish --build --repository test-pypi

- name: Publish to PyPI
  if: startsWith(github.ref, &#39;refs/tags/v&#39;)
  run: poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;このアプローチは意図しない公開を防ぎます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_renovate_と_dependabot_を使った依存関係の自動化&quot;&gt;Renovate と Dependabot を使った依存関係の自動化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;依存関係が古くなるのを防ぐため、自動更新ツールを組み込んでください。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dependabot&quot;&gt;Dependabot&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;version: 2
updates:
  - package-ecosystem: &quot;pip&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;
  - package-ecosystem: &quot;github-actions&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dependabotは毎週、PythonおよびGitHub Actionsの依存関係を更新するためにPRを開きます。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_リノベート&quot;&gt;リノベート&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;extends&quot;: [&quot;config:base&quot;],
  &quot;packageRules&quot;: [
    {
      &quot;matchManagers&quot;: [&quot;pip&quot;],
      &quot;groupName&quot;: &quot;python-dependencies&quot;,
      &quot;schedule&quot;: [&quot;before 6am on monday&quot;]
    }
  ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Renovateはより細かい制御を可能にします：依存関係のグループ化、スケジューリング、および高度なルール。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_plantuml図&quot;&gt;PlantUML図&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ユースケース_高度なcicd&quot;&gt;ユースケース – 高度なCI/CD&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Developer
actor GitHub as &quot;GitHub アクション&quot;
actor PyPI
actor DockerRegistry as &quot;Docker レジストリ&quot;
actor Automation as &quot;リノベート/Dependabot&quot;

Developer --&amp;gt; (Push code)
(Trigger CI) --&amp;gt; GitHub
GitHub --&amp;gt; (Run Tests &amp;amp; Lint)
GitHub --&amp;gt; (Build Docker Image)
GitHub --&amp;gt; DockerRegistry
GitHub --&amp;gt; (Publish to Test PyPI)
GitHub --&amp;gt; (Promote to PyPI)
Automation --&amp;gt; (Update Dependencies)
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_シーケンス_条件付き公開&quot;&gt;シーケンス – 条件付き公開&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme vibrant
left to right direction
Developer -&amp;gt; GitHub: Push tag v1.2.3-rc
GitHub -&amp;gt; CI: Run tests
CI -&amp;gt; CD: Check release type
CD -&amp;gt; Test PyPI: Publish RC
Developer -&amp;gt; GitHub: Push tag v1.2.3
GitHub -&amp;gt; CD: Publish to PyPI
CD -&amp;gt; Docker Registry: Push Docker image
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ステータス_cicd_パイプライン&quot;&gt;ステータス – CI/CD パイプライン&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
[*] --&amp;gt; Idle
Idle --&amp;gt; CI_Running : push
CI_Running --&amp;gt; CI_Success : tests ok
CI_Running --&amp;gt; CI_Failed : tests fail
CI_Success --&amp;gt; CD_Running : tag detected
CD_Running --&amp;gt; CD_Success : publish ok
CD_Running --&amp;gt; CD_Failed : error
CD_Success --&amp;gt; [*]
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_デプロイメント_cicdアーキテクチャ&quot;&gt;デプロイメント – CI/CDアーキテクチャ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;開発者用マシン&quot; {
  component &quot;Git クライアント&quot;
}

node &quot;GitHub Actions&quot; {
  component &quot;CI ワークフロー&quot;
  component &quot;CD ワークフロー&quot;
}

node &quot;パッケージリポジトリ&quot; {
  artifact &quot;テスト PyPI&quot;
  artifact &quot;PyPI&quot;
  artifact &quot;Dockerレジストリ&quot;
}

&quot;開発者用マシン&quot; --&amp;gt; &quot;GitHub Actions&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;テスト PyPI&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;PyPI&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;Dockerレジストリ&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_結論&quot;&gt;結論&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;この第三部では、次のことを見ました： - Poetryを使用してPythonパッケージングをモダン化する。 - Dockerを使用して再現可能なビルドを保証する。 - 条件付き公開を設定する。 依存関係の更新を自動化する。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;あなたは今ではCI/CDパイプラインを持っています&lt;strong&gt;完全、工業化され、安全&lt;/strong&gt;, あなたのプロジェクトとともに進化する準備ができています。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_導入&quot;&gt;導入&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cicdパイプラインのアーキテクチャ&quot;&gt;CI/CDパイプラインのアーキテクチャ&lt;/a&gt;&lt;/li&gt;
