&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;toc_ts&quot;&gt;&lt;span class=&quot;underline&quot;&gt;Intro typescript&lt;/span&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#ts_types&quot;&gt;TypeScriptの型&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#機能&quot;&gt;[機能]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#data_struct&quot;&gt;データ構造&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#enums_tuples&quot;&gt;列挙型とタプル&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#void_never&quot;&gt;Void と Never&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
