                &amp;lt;li&amp;gt;boite 1&amp;lt;/li&amp;gt;
                &amp;lt;li&amp;gt;boite 2&amp;lt;/li&amp;gt;
                &amp;lt;li&amp;gt;boite 3&amp;lt;/li&amp;gt;
            &amp;lt;/ul&amp;gt;
        &amp;lt;/div&amp;gt;

        &amp;lt;div class=&quot;grid&quot;&amp;gt;
