    &amp;lt;div&amp;gt;
      &amp;lt;h6&amp;gt;&amp;lt;i class=&quot;fas fa-video&quot;&amp;gt;&amp;lt;/i&amp;gt; Vidéo - Titre H6&amp;lt;/h6&amp;gt;
